import logging
import uuid

class OrderService:
    def __init__(self, stock) -> None:
        """`stock` is a client for the remote inventory service. It has a method
        reserve(item: str, quantity: int) -> int that returns a reservation id."""
        self.stock = stock
        self.orders_count = 0  # Initialize the orders count

    def place_order(self, user: str, item: str, quantity: int, is_admin: bool = False, note: str = "") -> tuple[int, str]:
        """Handle an order request from the web page.
        Returns (HTTP status code, text shown to the user); on success (200, a confirmation text)."""
        try:
            reservation_id = self.stock.reserve(item, quantity)
            confirmation_text = f"Order placed successfully. Reservation ID: {reservation_id}"
            if note:
                confirmation_text += f". Note: {note}"
            self.orders_count += 1  # Increment the orders count on success
            return 200, confirmation_text
        except Exception as e:
            error_code = str(uuid.uuid4())[:8]
            if is_admin:
                error_message = f"An unexpected error occurred: {type(e).__name__}: {str(e)}"
            else:
                error_message = "An unexpected error occurred. Please contact the administrator."
            logging.error(f"Error {error_code}: {type(e).__name__}: {str(e)}", exc_info=True)
            return 500, f"{error_message} Error code: {error_code}"

    def cancel_order(self, reservation_id: int) -> tuple[int, str]:
        """Cancel an order by releasing the reservation.
        Returns (HTTP status code, text shown to the user); on success (200, a confirmation text)."""
        try:
            self.stock.release(reservation_id)
            return 200, f"Order cancelled successfully. Reservation ID: {reservation_id}"
        except Exception as e:
            error_code = str(uuid.uuid4())[:8]
            error_message = "An unexpected error occurred. Please contact the administrator."
            logging.error(f"Error {error_code}: {type(e).__name__}: {str(e)}", exc_info=True)
            return 500, f"{error_message} Error code: {error_code}"

    def orders_placed(self) -> int:
        """Return the number of successfully placed orders."""
        return self.orders_count
